function ler(rel) {
  const p = path.join(raiz, ...rel.split("/"));
  return fs.existsSync(p) ? fs.readFileSync(p, "utf8") : null;
}

if (!fs.existsSync(alvo)) {
  console.log("[erro] Nao achei app/(app)/clientes/components/ClienteClinicoTabs.tsx.");
  console.log("       Rode este comando dentro da pasta do projeto.");
  process.exit(1);
}

const atual = fs.readFileSync(alvo, "utf8");
if (atual.includes('id: "pacotes"')) {
  console.log("[pulou] A aba Pacotes ja existe neste arquivo. Nada foi alterado.");
  console.log("        Se ela nao aparece na tela, me mande um print.");
  process.exit(0);
}

const conferir = [
  ["actions/pacote.actions.ts", "registrarPagamentoPacote", "acoes de pacote"],
  ["actions/cliente-clinico.actions.ts", "editarEvolucaoCliente", "edicao de evolucao"],
  ["app/(app)/clientes/types.ts", "ClientePacoteData", "tipos de pacote"],
  ["app/(app)/clientes/types.ts", "ClienteContaFinanceiraOption", "contas da ficha"],
  ["app/(app)/clientes/[id]/page.tsx", "pacotes: pacotes.map", "pacotes nos dados da ficha"],
  ["components/atendimento/RegistrarEvolucaoPendenteModal.tsx", "export default", "janela de evolucao pendente"],
];
let faltou = false;
for (const [rel, trecho, nome] of conferir) {
  const t = ler(rel);
  if (!t || !t.includes(trecho)) {
    console.log("[erro] Falta: " + nome + " (" + rel + ")");
    faltou = true;
  } else {
    console.log("[ok] Encontrado: " + nome);
  }
}
if (faltou) {
  console.log("");
  console.log("Nada foi gravado. Outras partes do sistema tambem voltaram para uma");
  console.log("versao antiga. Me mande esta tela que eu preparo a correcao completa.");
  process.exit(1);
}

const crlf = atual.includes("\r\n");
const final = crlf ? NOVO.replace(/\r?\n/g, "\r\n") : NOVO;
fs.writeFileSync(alvo + ".antes-de-restaurar", atual);
fs.writeFileSync(alvo, final);
console.log("[ok] Copia do arquivo antigo guardada em ClienteClinicoTabs.tsx.antes-de-restaurar");
console.log("[ok] Aba Pacotes restaurada na ficha da cliente.");
console.log("");
console.log("IMPORTANTE: apague o arquivo antigo ocultar-fotos-por-padrao.mjs da pasta");
console.log("do projeto (se ele estiver la), para nao rodar ele de novo sem querer.");
console.log("");
console.log("Concluido.");
